const rowLocales = ['en','hu','de','fr'];
export const locales = [...rowLocales, 'ja'];
export const dictionaries = {...Object.fromEntries(rowLocales.map((locale,index)=>[locale,Object.fromEntries(rows.map(row=>[row[0],row[index+1]]))])), ja: japanese};
export function translator(locale='en') { const dictionary=dictionaries[locale]||dictionaries.en; return (key,values={}) => String(dictionary[key]??dictionaries.en[key]??key).replace(/\{(\w+)\}/g,(_,name)=>String(values[name]??`{${name}}`)); }
export function localeCode(locale){return {en:'en-GB',hu:'hu-HU',de:'de-DE',fr:'fr-FR',ja:'ja-JP'}[locale]||'en-GB';}
